380	// The classifier must accept both complete answers and reject ordered-looking
381	// mixtures and plain corruption.
382	func TestClassifyTxPageRejectsMixedAndCorruptPages(t *testing.T) {
383		oldRef := literalOldFirstPage()
384		newRef := literalNewFirstPage()
385		oldAll := referenceTxHits(queryOldChainBlocks())
386		newAll := referenceTxHits(queryNewChainBlocks())
387		classify := func(page TxPage) error { return classifyTxPage(page, oldRef, newRef, oldAll, newAll) }
388		if err := classify(oldRef); err != nil {
389			t.Fatalf("pure old page rejected: %v", err)
390		}
391		if err := classify(newRef); err != nil {
392			t.Fatalf("pure new page rejected: %v", err)
393		}
394	
395		// Mixture 1: shared first-page records (identical on both chains), but
396		// new-chain counts under the OLD tip height. Hit count still equals the
397		// total on both chains, so a count-equality check would accept it.
398		mixed1 := newRef
399		mixed1.ToHeight = oldRef.ToHeight
400		if int64(len(mixed1.Hits)) != 3 || mixed1.TotalMatches != 8 {
401			t.Fatal("test setup: mixed1 counts are meant to look internally consistent")
402		}
403		if err := classify(mixed1); err == nil {
404			t.Fatal("new-chain counts under the old tip height were accepted")
405		} else if !strings.Contains(err.Error(), "MIXED") {
406			t.Fatalf("mixed1 not reported as MIXED:\n%v", err)
407		}
408	
409		// Mixture 2: old-chain counts and records under the NEW shortened tip
410		// height — claims tip 4 while still counting removed height 5.
411		mixed2 := oldRef
412		mixed2.ToHeight = newRef.ToHeight
413		if err := classify(mixed2); err == nil {
414			t.Fatal("old-chain counts under the new tip height were accepted")
415		} else if !strings.Contains(err.Error(), "MIXED") {
416			t.Fatalf("mixed2 not reported as MIXED:\n%v", err)
417		}
418	
419		// Mixture 3: an ordered-looking page (height 3 positions 0 and 1) that
420		// stitches one old-branch record to one new-branch record, tagged old by
421		// its stale tip height.
422		mixed3 := oldRef
423		mixed3.Hits = []TxHit{
424			{Height: 3, BlockHash: "h3", TxID: "a", Position: 0},
425			{Height: 3, BlockHash: "j3", TxID: "q", Position: 1},
426		}
427		if err := classify(mixed3); err == nil {
428			t.Fatal("stitched hits from both branches were accepted")
429		} else if !strings.Contains(err.Error(), "MIXED") {
430			t.Fatalf("mixed3 not reported as MIXED:\n%v", err)
431		}
432	
433		// Corruption: stats belonging to no chain at all.
434		corrupt := newRef
435		corrupt.MatchedBlocks = 99
436		if err := classify(corrupt); err == nil {
437			t.Fatal("corrupt stats matching neither chain were accepted")
438		}
439	}
