431			{Height: 2, BlockHash: "h2", TxID: "a", Position: 1},
432			{Height: 2, BlockHash: "h2", TxID: "a", Position: 0},
433			{Height: 1, BlockHash: "h1", TxID: "a", Position: 0},
434		}
435		if !reflect.DeepEqual(page.Hits, want) {
436			t.Fatalf("desc order drifted with timestamps: %v, want %v", page.Hits, want)
437		}
438	}
439	
440	// TestQueryTxsRejectsInvalidOrder: unknown order values are argument errors.
441	func TestQueryTxsRejectsInvalidOrder(t *testing.T) {
442		index := txChain(t, []string{"a"})
443		if _, err := index.QueryTxs(TxQuery{Order: TxOrder(2)}); !errors.Is(err, ErrInvalidArgument) {
444			t.Fatalf("invalid order: err=%v, want ErrInvalidArgument", err)
445		}
446		if _, err := index.QueryTxs(TxQuery{Order: TxOrder(-1)}); !errors.Is(err, ErrInvalidArgument) {
447			t.Fatalf("negative order: err=%v, want ErrInvalidArgument", err)
448		}
449	}
450	
451	// TestScanPageLockedDescWindow is the descending twin of the ascending
452	// window contract: each offset slices the oracle's fully-reversed occurrence
453	// list, at most pageSize records retained, totals unchanged.
454	func TestScanPageLockedDescWindow(t *testing.T) {
455		var blocks [][]string
456		for h := 0; h < 40; h++ {
457			blocks = append(blocks, []string{
458				fmt.Sprintf("t%d", h%5),
459				"keep",
460				"keep",
461			})
462		}
463		index := txChain(t, blocks...)
464		const from, to = int64(1), int64(40)
465	
466		ascAll, matchedBlocks := referenceScan(index, from, to, nil)
467		wantAll := make([]TxHit, len(ascAll))
468		for i, hit := range ascAll {
469			wantAll[len(ascAll)-1-i] = hit
470		}
471	
472		for _, pageSize := range []int{1, 3, DefaultPageSize, MaxPageSize} {
473			var windowed []TxHit
474			for offset := int64(0); ; {
475				hits, total, gotBlocks := index.scanPageLocked(from, to, newTxFilter(nil), OrderDesc, offset, pageSize)
476				if total != int64(len(wantAll)) || gotBlocks != matchedBlocks {
477					t.Fatalf("pageSize=%d offset=%d: totals=%d/%d want %d/%d",
478						pageSize, offset, total, gotBlocks, len(wantAll), matchedBlocks)
479				}
480				if cap(hits) > pageSize {
481					t.Fatalf("pageSize=%d retained cap=%d", pageSize, cap(hits))
482				}
483				end := offset + int64(len(hits))
484				if end > int64(len(wantAll)) || !reflect.DeepEqual(hits, wantAll[offset:end]) {
485					t.Fatalf("pageSize=%d offset=%d: desc window mismatch", pageSize, offset)
486				}
487				windowed = append(windowed, hits...)
488				if len(hits) < pageSize {
489					break
490				}
491				offset = end
492			}
493			if !reflect.DeepEqual(windowed, wantAll) {
494				t.Fatalf("pageSize=%d: desc windows do not reconstruct the reversed list", pageSize)
495			}
496		}
497	}
498	
499	// TestQueryTxsDescConcurrentWithAppends mirrors the ascending concurrency
500	// test: descending readers always see one consistent pinned range and a
501	// strictly decreasing occurrence sequence.
502	func TestQueryTxsDescConcurrentWithAppends(t *testing.T) {
503		index := chain(t, Block{Height: 1, Hash: "h1", Parent: "genesis", Txs: []string{"tx-1"}})
504		stop := make(chan struct{})
505	
506		var writer sync.WaitGroup
507		writer.Add(1)
508		go func() {
509			defer writer.Done()
510			for height := int64(2); height <= 200; height++ {
511				select {
512				case <-stop:
513					return
514				default:
515				}
516				block := Block{
517					Height: height,
518					Hash:   fmt.Sprintf("h%d", height),
519					Parent: fmt.Sprintf("h%d", height-1),
520					Txs:    []string{fmt.Sprintf("tx-%d", height)},
521				}
522				if err := index.Append(block); err != nil {
523					return
524				}
525			}
526		}()
527	
528		var readers sync.WaitGroup
529		for reader := 0; reader < 4; reader++ {
530			readers.Add(1)
531			go func() {
532				defer readers.Done()
533				for round := 0; round < 20; round++ {
534					pages := 0
535					seen := 0
536					var total, matched, to int64 = -1, -1, -1
537					query := TxQuery{PageSize: 7, Order: OrderDesc}
538					var lastHeight int64 = 1 << 62
539					lastPosition := 1 << 30
540					for {
541						page, err := index.QueryTxs(query)
542						if err != nil {
543							t.Errorf("desc query failed during appends: %v", err)
544							return
545						}
546						if total == -1 {
547							total, matched, to = page.TotalMatches, page.MatchedBlocks, page.ToHeight
548						} else if page.TotalMatches != total || page.MatchedBlocks != matched || page.ToHeight != to {
549							t.Errorf("desc stats changed mid-pagination: %+v", page)
550							return
551						}
552						for _, hit := range page.Hits {
553							if hit.Height > lastHeight || (hit.Height == lastHeight && hit.Position >= lastPosition) {
554								t.Errorf("desc hits out of order after (%d,%d): %+v", lastHeight, lastPosition, hit)
555								return
556							}
557							lastHeight, lastPosition = hit.Height, hit.Position
558						}
559						seen += len(page.Hits)
560						pages++
561						if page.NextCursor == "" {
562							break
563						}
564						query.Cursor = page.NextCursor
565					}
566					if int64(seen) != total {
567						t.Errorf("desc paginated %d hits over %d pages, total says %d", seen, pages, total)
568						return
569					}
570				}
571			}()
572		}
573		readers.Wait()
574		close(stop)
575		writer.Wait()
576	}
